package com.personalassistant.companion;

import android.app.*;
import android.content.*;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

/**
 * The live session. Every entry saves to the on-phone draft, every clock is wall-clock arithmetic from saved instants, and nothing
 * here needs the network. Weight and reps stay editable throughout, prefilled from the sprint target, and the structure can be
 * changed freely: sets, exercises, order, supersets and notes. Unticked sets are left out when the workout finishes.
 */
final class WorkoutLive {
    final WorkoutScreen screen;final MainActivity a;final AppUi ui;JSONObject d;final Dialog dialog;final LinearLayout root,list,bar;final ScrollView scroll;final TextView clock,pace,pauseLabel;final Handler main=new Handler(Looper.getMainLooper());boolean closed;int reordering=-1,actions=-1;
    private final Runnable tick=new Runnable(){public void run(){if(closed)return;update();main.postDelayed(this,1000);}};
    private final Runnable save=new Runnable(){public void run(){WorkoutStore.saveDraft(ui.context,d);}};

    static JSONObject blank(Context c,String name,String template,String sprint,String date)throws JSONException{long now=System.currentTimeMillis();return new JSONObject().put("workout_id",WorkoutStore.id()).put("name",name).put("started_ms",now).put("timezone",ZoneId.systemDefault().getId()).put("template_id",template==null?JSONObject.NULL:template).put("sprint_id",sprint==null?JSONObject.NULL:sprint).put("scheduled_date",date==null?"":date).put("paused_ms",0).put("paused_total",0).put("notes","").put("changes",new JSONArray()).put("exercises",new JSONArray());}
    /** One planned exercise, set by set. Prescribed loads win, then this sprint's last session; an old record is never a prefill. */
    static JSONObject planned(Context c,JSONObject p,String sprint)throws JSONException{String id=p.optString("exercise_id");boolean run=WorkoutStore.cardio(c,id);int rest=p.optInt("rest_seconds",120);JSONObject row=new JSONObject().put("eid",id).put("rest",rest).put("note",p.optString("notes")).put("group",p.optString("superset")).put("started_ms",0).put("ended_ms",0);
        List<JSONObject> earlier=new ArrayList<>();if(sprint!=null)for(JSONObject w:WorkoutStore.workouts(c)){JSONObject x=w.optJSONObject("data");if(!sprint.equals(x.optString("sprint_id"))||!"completed".equals(x.optString("status")))continue;JSONArray s=x.optJSONArray("sets");for(int i=0;s!=null&&i<s.length();i++)if(id.equals(s.optJSONObject(i).optString("exercise_id"))&&"working".equals(s.optJSONObject(i).optString("kind")))earlier.add(s.optJSONObject(i));if(!earlier.isEmpty())break;}
        JSONArray plan=WorkoutPlan.sets(c,p),sets=new JSONArray();int hard=0;for(int i=0;i<plan.length();i++){JSONObject q=plan.getJSONObject(i);String kind=q.optString("kind","working");JSONObject set=new JSONObject().put("id",WorkoutStore.id()).put("kind",kind).put("done",false);
            if(run){if(q.optDouble("distance_m",0)>0)set.put("distance",q.optDouble("distance_m"));if(q.optLong("seconds")>0)set.put("seconds",q.optLong("seconds"));}
            else{JSONObject last=earlier.isEmpty()||"warmup".equals(kind)?null:earlier.get(Math.min(hard,earlier.size()-1));if(!"warmup".equals(kind))hard++;double w=q.isNull("weight_kg")?(last==null?0:last.optDouble("weight_kg",0)):q.optDouble("weight_kg",0);if(w>0)set.put("weight",w);if(q.optInt("reps")>0)set.put("reps",q.optInt("reps"));if(!q.isNull("rir"))set.put("rir",q.optDouble("rir"));}sets.put(set);}
        row.put("sets",sets);row.put("planned",p.has("estimated_seconds")&&!p.isNull("estimated_seconds")?p.optInt("estimated_seconds"):run&&p.optDouble("distance_m",0)>0&&p.optDouble("speed_kmh",0)>0?(int)(p.optDouble("distance_m")/(p.optDouble("speed_kmh")/3.6)):plan.length()*(45+rest)+60);return row;}
    static JSONObject fromTemplate(Context c,String name,String template,String sprint,String date,String shortenTo)throws JSONException{JSONObject d=blank(c,name,template,sprint,date);JSONObject t=template==null?null:WorkoutStore.data(c,"template",template);JSONArray ex=t==null?null:t.optJSONArray("exercises");for(int i=0;ex!=null&&i<ex.length();i++)d.getJSONArray("exercises").put(planned(c,ex.getJSONObject(i),sprint));if(d.getJSONArray("exercises").length()>0)d.getJSONArray("exercises").getJSONObject(0).put("started_ms",d.optLong("started_ms"));return d;}

    WorkoutLive(WorkoutScreen s,JSONObject draft){screen=s;a=s.a;ui=s.ui;d=draft;dialog=ui.sheet();dialog.setCancelable(true);root=ui.column();root.setBackgroundColor(ui.background);root.setFitsSystemWindows(true);
        LinearLayout top=ui.row();top.setPadding(ui.dp(6),ui.dp(6),ui.dp(10),0);top.addView(ui.iconButton("down","Minimise workout",this::close),new LinearLayout.LayoutParams(ui.dp(46),ui.dp(46)));TextView title=ui.type(d.optString("name"),15,20,600,0,ui.muted);title.setSingleLine(true);title.setEllipsize(TextUtils.TruncateAt.END);title.setOnClickListener(v->rename());top.addView(title,MainParts.weighted(ui,1,4,0,6,0));
        pauseLabel=ui.type("Pause",14,20,600,0,ui.accent);pauseLabel.setPadding(ui.dp(10),ui.dp(12),ui.dp(12),ui.dp(12));pauseLabel.setOnClickListener(v->pause());top.addView(pauseLabel);Button finish=ui.quietButton("Finish",this::finish);finish.setTag("workout_finish");top.addView(finish,new LinearLayout.LayoutParams(-2,ui.dp(46)));root.addView(top);
        LinearLayout head=ui.row();head.setPadding(ui.dp(16),0,ui.dp(16),ui.dp(6));clock=ui.type("0:00",32,38,800,-.02f,ui.text);clock.setTag("workout_clock");head.addView(clock,new LinearLayout.LayoutParams(0,-2,1));pace=ui.type("",12.5f,17,600,0,ui.muted);pace.setGravity(Gravity.END);head.addView(pace);root.addView(head);
        bar=ui.row();root.addView(bar,MainParts.params(ui,-1,ui.dp(8),16,0,16,8));
        scroll=new ScrollView(a);list=ui.column();list.setPadding(ui.dp(12),ui.dp(2),ui.dp(12),ui.dp(28));scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(root);render();
        dialog.setOnDismissListener(v->{closed=true;main.removeCallbacks(tick);main.removeCallbacks(save);WorkoutStore.saveDraft(ui.context,d);screen.liveClosed();});}
    void show(){dialog.show();Window w=dialog.getWindow();if(w!=null){w.setLayout(-1,-1);w.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);}main.post(tick);}
    void close(){dialog.dismiss();}
    private JSONArray exercises(){return d.optJSONArray("exercises");}
    private void changed(){main.removeCallbacks(save);main.postDelayed(save,300);}
    private void note(String kind,String text){try{d.getJSONArray("changes").put(new JSONObject().put("id",WorkoutStore.id()).put("at",iso(System.currentTimeMillis())).put("kind",kind).put("reason",text));}catch(JSONException ignored){}}
    private String iso(long ms){return OffsetDateTime.ofInstant(Instant.ofEpochMilli(ms),ZoneId.of(d.optString("timezone","UTC"))).withNano(0).toString();}
    private long elapsed(){long now=d.optLong("paused_ms")>0?d.optLong("paused_ms"):System.currentTimeMillis();return Math.max(0,now-d.optLong("started_ms")-d.optLong("paused_total"));}

    void update(){clock.setText(WorkoutViews.clock(elapsed()/1000));pauseLabel.setText(d.optLong("paused_ms")>0?"Resume":"Pause");long plan=0,left=0,now=System.currentTimeMillis();JSONArray ex=exercises();for(int i=0;i<ex.length();i++){JSONObject e=ex.optJSONObject(i);long p=e.optLong("planned")*1000;plan+=p;if(e.optLong("ended_ms")>0)continue;long spent=e.optLong("started_ms")>0?now-e.optLong("started_ms"):0;left+=Math.max(0,p-spent);}
        if(plan>0){long projected=elapsed()+left,diff=(plan-projected)/60000;java.time.LocalTime end=java.time.LocalTime.now().plusSeconds(left/1000);pace.setText((diff==0?"On plan":Math.abs(diff)+" min "+(diff>0?"ahead":"behind"))+"\nEnds about "+end.format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"))+" · "+projected/60000+" min");pace.setTextColor(diff<-3?ui.warning:diff>=0?ui.success:ui.muted);}else pace.setText("");
        bar();}
    private int barKey=-1;
    private void bar(){int key=0;JSONArray ex=exercises();for(int i=0;i<ex.length();i++)key=key*31+(ex.optJSONObject(i).optLong("ended_ms")>0?2:ex.optJSONObject(i).optLong("started_ms")>0?1:0)+ex.optJSONObject(i).optInt("planned")/30;if(key==barKey)return;barKey=key;bar.removeAllViews();for(int i=0;i<ex.length();i++){JSONObject e=ex.optJSONObject(i);View part=new View(a);part.setBackground(ui.outline(e.optLong("ended_ms")>0?ui.success:e.optLong("started_ms")>0?ui.accent:ui.stroke,4,0,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,Math.max(1,e.optInt("planned",60)));p.setMarginEnd(ui.dp(2));bar.addView(part,p);}}

    void render(){if(reordering>=0){reorderList();return;}list.removeAllViews();JSONArray ex=exercises();for(int i=0;i<ex.length();i++){list.addView(card(i));if(i+1<ex.length())list.addView(linkBar(i));}
        LinearLayout tools=ui.row();Button add=ui.quietButton("Add exercise",()->WorkoutPlan.pick(screen,id->{try{JSONObject p=new JSONObject().put("exercise_id",id).put("sets",1).put("rest_seconds",120);p.put("min_reps",0);exercises().put(planned(a,p,null));note("edit_exercises","Added "+WorkoutStore.exerciseName(a,id));save.run();render();}catch(JSONException ignored){}}));add.setTag("workout_add_exercise");tools.addView(add,new LinearLayout.LayoutParams(0,-2,1));tools.addView(ui.iconButton("sparkle","Ask your coach",ui.hue(AppUi.VIOLET),this::trainer),MainParts.params(ui,ui.dp(48),ui.dp(48),8,0,0,0));list.addView(tools,MainParts.params(ui,-1,-2,0,12,0,8));
        EditText notes=ui.field("Workout notes",d.optString("notes"));notes.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);notes.addTextChangedListener(new Watch(s->{put(d,"notes",s);changed();}));list.addView(notes,WorkoutViews.gap(ui,8));
        list.addView(ui.ghostButton("Cancel workout",this::cancel));barKey=-1;update();}

    private JSONObject exercise(int i){return exercises().optJSONObject(i);}
    private static final int[] GROUP={AppUi.TEAL,AppUi.PINK,AppUi.AMBER,AppUi.BLUE};
    /** Supersets are numbered down the workout, each with its own colour. */
    private int groupHue(int index){String g=exercise(index).optString("group");if(g.isEmpty())return 0;ArrayList<String> seen=new ArrayList<>();for(int i=0;i<=index;i++){String x=exercise(i).optString("group");if(!x.isEmpty()&&!seen.contains(x))seen.add(x);}return ui.hue(GROUP[(seen.size()-1)%GROUP.length]);}
    /** The join between two exercises: tap to superset them, tap a link further down to extend it, tap a lit link to break it there. */
    private View linkBar(int i){boolean on=!exercise(i).optString("group").isEmpty()&&exercise(i).optString("group").equals(exercise(i+1).optString("group"));int tint=on?groupHue(i):ui.muted;FrameLayout f=new FrameLayout(a);if(on){View line=new View(a);line.setBackgroundColor(tint);f.addView(line,new FrameLayout.LayoutParams(ui.dp(3),-1,Gravity.CENTER));}ImageButton b=ui.iconButton("link",on?"Break superset":"Superset with next",tint,()->link(i));b.setTag("workout_link");b.setMinimumWidth(0);b.setMinimumHeight(0);f.addView(b,new FrameLayout.LayoutParams(ui.dp(38),ui.dp(38),Gravity.CENTER));return f;}
    private void link(int i){try{JSONObject e=exercise(i),n=exercise(i+1);String g=e.optString("group"),h=n.optString("group");if(!g.isEmpty()&&g.equals(h)){String tail=WorkoutStore.id();for(int k=i+1;k<exercises().length()&&g.equals(exercise(k).optString("group"));k++)exercise(k).put("group",tail);note("edit_exercises","Split a superset");}else{String join=g.isEmpty()?(h.isEmpty()?WorkoutStore.id():h):g;e.put("group",join);for(int k=i+1;k<exercises().length()&&(k==i+1||!h.isEmpty()&&h.equals(exercise(k).optString("group")));k++)exercise(k).put("group",join);note("edit_exercises","Linked a superset");}tidy();save.run();render();}catch(JSONException ignored){}}
    /** A superset is a run of neighbours: moving or removing an exercise splits runs, and a lone exercise leaves its group. */
    private void tidy(){try{HashSet<String> used=new HashSet<>();int n=exercises().length();for(int i=0;i<n;){String g=exercise(i).optString("group");int j=i+1;while(j<n&&!g.isEmpty()&&g.equals(exercise(j).optString("group")))j++;if(!g.isEmpty()){String id=j-i<2?"":used.add(g)?g:WorkoutStore.id();for(int k=i;k<j;k++)exercise(k).put("group",id);}i=j;}}catch(JSONException ignored){}}

    private View card(int index){JSONObject e=exercise(index);String id=e.optString("eid");boolean run=WorkoutStore.cardio(a,id);JSONObject info=WorkoutStore.data(a,"exercise",id);LinearLayout box=WorkoutViews.card(ui);box.setPadding(ui.dp(12),ui.dp(8),ui.dp(8),ui.dp(10));int tint=groupHue(index);if(tint!=0)box.setBackground(ui.outline(ui.surface,18,tint,2));
        LinearLayout head=ui.row();View art=WorkoutArt.tile(ui,id,44);head.addView(art,new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));LinearLayout words=ui.column();words.addView(ui.type(WorkoutStore.exerciseName(a,id),16,21,700,0,WorkoutArt.hue(ui,info)));String sub=target(e);if(!sub.isEmpty())words.addView(ui.type(sub,12,16,400,0,ui.muted));head.addView(words,MainParts.weighted(ui,1,10,0,0,0));head.addView(ui.iconButton("more","Exercise options",()->{actions=actions==index?-1:index;render();}),new LinearLayout.LayoutParams(ui.dp(42),ui.dp(42)));box.addView(head);words.setTag("workout_exercise_name");for(View v:new View[]{art,words}){v.setContentDescription("Open "+WorkoutStore.exerciseName(a,id)+" history");v.setOnClickListener(x->screen.history.exercise(id));v.setOnLongClickListener(x->{reordering=index;render();return true;});}
        if(actions==index){LinearLayout tools=ui.row();Object[][] items={{"refresh","Replace exercise",AppUi.BLUE,(Runnable)()->replace(index)},{"grip","Reorder exercises",AppUi.VIOLET,(Runnable)()->{reordering=index;actions=-1;render();}},{"chat","Note",AppUi.AMBER,(Runnable)()->noteOn(index)},{"trash","Remove exercise",AppUi.RED,(Runnable)()->removeExercise(index)}};for(Object[] t:items)tools.addView(ui.iconButton((String)t[0],(String)t[1],ui.hue((Integer)t[2]),(Runnable)t[3]),new LinearLayout.LayoutParams(0,ui.dp(48),1));box.addView(tools,MainParts.params(ui,-1,-2,0,4,0,0));}
        LinearLayout cols=ui.row();cols.setPadding(0,ui.dp(4),ui.dp(42),ui.dp(2));String unit=run?WorkoutUnits.distanceLabel(a,id):WorkoutUnits.loadLabel(a,id);String[][] names=run?new String[][]{{"Set","34"},{"Previous","0"},{unit,"0"},{"Time","0"}}:new String[][]{{"Set","34"},{"Previous","0"},{unit,"0"},{"Reps","0"},{"RIR","46"}};for(String[] n:names){boolean switcher=n[0].equals(unit);TextView t=ui.type(n[0],switcher?12.5f:11.5f,16,switcher?800:600,0,switcher?ui.accent:ui.muted);t.setGravity(Gravity.CENTER);if(switcher){t.setTag("workout_unit");t.setContentDescription("Unit "+unit+". Tap to switch for this exercise");t.setPadding(0,ui.dp(5),0,ui.dp(5));t.setBackground(ui.outline(ui.accentSoft,9,0,0));t.setOnClickListener(v->{WorkoutUnits.flip(a,id);v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);render();});}cols.addView(t,n[1].equals("0")?new LinearLayout.LayoutParams(0,-2,n[0].equals("Previous")?1.25f:1):new LinearLayout.LayoutParams(ui.dp(Integer.parseInt(n[1])),-2));}box.addView(cols);
        List<JSONObject> before=WorkoutStore.previous(a,id);JSONArray sets=e.optJSONArray("sets");int number=0;for(int i=0;i<sets.length();i++){JSONObject s=sets.optJSONObject(i);if("working".equals(s.optString("kind")))number++;String old="–";JSONObject b=previousFor(before,sets,i);if(b!=null)old=run?WorkoutUnits.distanceNumber(a,id,b.optDouble("distance_m",0))+" · "+WorkoutViews.clock(b.optLong("seconds")):WorkoutUnits.loadNumber(a,id,b.optDouble("weight_kg",0))+" × "+b.optInt("reps");box.addView(setRow(index,i,s,number,old,run));}
        Button add=ui.ghostButton("Add set",()->addSet(index));add.setTag("workout_add_set");box.addView(add,MainParts.params(ui,-1,ui.dp(42),0,4,4,0));
        if(!e.optString("note").isEmpty()){TextView n=ui.type(e.optString("note"),12.5f,17,400,0,ui.muted);box.addView(n);}return box;}
    /** The same kind of set from last time: warm-ups line up with warm-ups, hard sets with hard sets. */
    private static JSONObject previousFor(List<JSONObject> before,JSONArray sets,int index){boolean warm="warmup".equals(sets.optJSONObject(index).optString("kind"));int nth=0;for(int i=0;i<index;i++)if("warmup".equals(sets.optJSONObject(i).optString("kind"))==warm)nth++;for(JSONObject b:before)if("warmup".equals(b.optString("kind"))==warm&&nth--==0)return b;return null;}
    private String target(JSONObject e){JSONObject t=d.isNull("template_id")?null:WorkoutStore.data(a,"template",d.optString("template_id"));JSONArray ex=t==null?null:t.optJSONArray("exercises");for(int i=0;ex!=null&&i<ex.length();i++){JSONObject p=ex.optJSONObject(i);if(!e.optString("eid").equals(p.optString("exercise_id")))continue;if(!p.isNull("distance_m")&&p.has("distance_m"))return "Target "+WorkoutUnits.distance(a,p.optDouble("distance_m"))+(p.has("speed_kmh")&&!p.isNull("speed_kmh")?" at "+WorkoutUnits.speed(a,p.optDouble("speed_kmh")):"");String reps=p.optInt("min_reps")==p.optInt("max_reps")?""+p.optInt("min_reps"):p.optInt("min_reps")+"–"+p.optInt("max_reps");return "Target "+p.optInt("sets",1)+" × "+reps+(p.isNull("rir")||!p.has("rir")?"":" · "+WorkoutViews.kg(p.optDouble("rir"))+" in reserve");}return "";}

    private EditText input(String value,boolean decimal,String label){EditText v=new EditText(a);v.setText(value);v.setTextSize(15);v.setTypeface(AppUi.face(600));v.setTextColor(ui.text);v.setGravity(Gravity.CENTER);v.setPadding(0,0,0,0);v.setSingleLine(true);v.setSelectAllOnFocus(true);v.setContentDescription(label);v.setInputType(decimal?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_NUMBER);v.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_NEXT);v.setBackground(ui.outline(ui.surfaceAlt,10,0,0));return v;}
    private static void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(JSONException ignored){}}
    private static void number(JSONObject s,String key,String text){if(text.trim().isEmpty()){s.remove(key);return;}try{put(s,key,Double.parseDouble(text.trim().replace(',','.')));}catch(NumberFormatException ignored){}}
    private static String shown(JSONObject s,String key){return s.has(key)?WorkoutViews.kg(s.optDouble(key)):"";}
    static final class Watch implements TextWatcher{final java.util.function.Consumer<String> to;Watch(java.util.function.Consumer<String> t){to=t;}public void afterTextChanged(Editable e){to.accept(e.toString());}public void beforeTextChanged(CharSequence c,int a,int b,int d){}public void onTextChanged(CharSequence c,int a,int b,int d){}}

    private View setRow(int ex,int index,JSONObject s,int number,String old,boolean run){String id=exercise(ex).optString("eid");LinearLayout r=new WorkoutViews.SwipeRow(ui,()->removeSet(ex,index),()->tick(ex,index));r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(0,ui.dp(2),0,ui.dp(2));boolean done=s.optBoolean("done");if(done)r.setBackground(ui.outline(ui.successSoft,10,0,0));String kind=s.optString("kind");TextView tag=WorkoutViews.setTag(ui,kind,number);tag.setTag("workout_set_type");tag.setOnClickListener(v->cycle(v,ex,index));r.addView(tag,MainParts.params(ui,ui.dp(30),ui.dp(34),2,0,2,0));
        TextView prev=ui.type(old,12,16,400,0,ui.muted);prev.setGravity(Gravity.CENTER);prev.setMaxLines(1);prev.setOnClickListener(v->usePrevious(ex,index));r.addView(prev,new LinearLayout.LayoutParams(0,-2,1.25f));
        LinearLayout.LayoutParams field=new LinearLayout.LayoutParams(0,ui.dp(40),1);field.setMarginEnd(ui.dp(4));
        if(run){EditText dist=input(s.has("distance")?WorkoutUnits.distanceNumber(a,id,s.optDouble("distance")):"",true,"Distance");dist.addTextChangedListener(new Watch(t->{try{if(t.trim().isEmpty())s.remove("distance");else put(s,"distance",WorkoutUnits.distanceIn(a,id,Double.parseDouble(t.trim().replace(',','.'))));}catch(NumberFormatException ignored){}changed();}));r.addView(dist,field);EditText time=input(s.has("seconds")?WorkoutViews.clock(s.optLong("seconds")):"",false,"Time in minutes and seconds");time.setInputType(InputType.TYPE_CLASS_DATETIME|InputType.TYPE_DATETIME_VARIATION_TIME);time.addTextChangedListener(new Watch(t->{long sec=seconds(t);if(sec>0)put(s,"seconds",sec);else s.remove("seconds");changed();}));r.addView(time,new LinearLayout.LayoutParams(0,ui.dp(40),1));}
        else{EditText w=input(s.has("weight")?WorkoutUnits.loadNumber(a,id,s.optDouble("weight")):"",true,"Weight");w.setTag("workout_kg");w.addTextChangedListener(new Watch(t->{try{if(t.trim().isEmpty())s.remove("weight");else put(s,"weight",WorkoutUnits.loadIn(a,id,Double.parseDouble(t.trim().replace(',','.'))));}catch(NumberFormatException ignored){}changed();}));r.addView(w,field);EditText reps=input(s.has("reps")?""+s.optInt("reps"):"",false,"Reps");reps.setTag("workout_reps");reps.addTextChangedListener(new Watch(t->{number(s,"reps",t);changed();}));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(0,ui.dp(40),1);rp.setMarginEnd(ui.dp(4));r.addView(reps,rp);EditText rir=input(shown(s,"rir"),true,"Reps in reserve");rir.addTextChangedListener(new Watch(t->{number(s,"rir",t);changed();}));r.addView(rir,new LinearLayout.LayoutParams(ui.dp(42),ui.dp(40)));}
        ImageButton check=ui.iconButton("check",done?"Unmark set":"Complete set",()->tick(ex,index));check.setTag("workout_check");check.setAlpha(done?1f:.45f);r.addView(check,new LinearLayout.LayoutParams(ui.dp(42),ui.dp(42)));return r;}
    private static long seconds(String t){try{String[] p=t.trim().split(":");long v=0;for(String x:p)v=v*60+Long.parseLong(x.trim());return p.length==1?v*60:v;}catch(NumberFormatException e){return 0;}}
    private void usePrevious(int ex,int index){JSONObject e=exercises().optJSONObject(ex);List<JSONObject> before=WorkoutStore.previous(a,e.optString("eid"));JSONObject b=previousFor(before,e.optJSONArray("sets"),index),s=e.optJSONArray("sets").optJSONObject(index);if(b==null)return;if(b.has("weight_kg")&&!b.isNull("weight_kg"))put(s,"weight",b.optDouble("weight_kg"));if(b.has("reps")&&!b.isNull("reps"))put(s,"reps",b.optInt("reps"));if(b.has("distance_m")&&!b.isNull("distance_m"))put(s,"distance",b.optDouble("distance_m"));if(b.has("seconds")&&!b.isNull("seconds"))put(s,"seconds",b.optLong("seconds"));save.run();render();}
    /** Tapping the set number steps through working, warm-up, drop and failure. */
    private void cycle(View v,int ex,int index){JSONObject s=exercise(ex).optJSONArray("sets").optJSONObject(index);List<String> order=Arrays.asList("working","warmup","drop","failure");put(s,"kind",order.get((order.indexOf(s.optString("kind"))+1)%order.size()));v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);save.run();render();}
    private void removeSet(int ex,int index){JSONObject e=exercises().optJSONObject(ex);e.optJSONArray("sets").remove(index);note("edit_exercises","Removed a set of "+WorkoutStore.exerciseName(a,e.optString("eid")));save.run();render();}
    private void addSet(int ex){try{JSONObject e=exercises().optJSONObject(ex);JSONArray sets=e.getJSONArray("sets");JSONObject set=sets.length()>0?new JSONObject(sets.getJSONObject(sets.length()-1).toString()):new JSONObject().put("kind","working");set.put("id",WorkoutStore.id()).put("done",false);if("warmup".equals(set.optString("kind")))set.put("kind","working");sets.put(set);note("edit_exercises","Added a set of "+WorkoutStore.exerciseName(a,e.optString("eid")));save.run();render();}catch(JSONException ignored){}}
    private void tick(int ex,int index){try{JSONObject e=exercises().getJSONObject(ex);String id=e.optString("eid");JSONObject s=e.getJSONArray("sets").getJSONObject(index);boolean run=WorkoutStore.cardio(a,id);if(!s.optBoolean("done")&&!(run?s.has("distance")&&s.has("seconds"):s.has("reps"))){Toast.makeText(a,run?"Enter distance and time":"Enter the reps",Toast.LENGTH_SHORT).show();return;}
            long now=System.currentTimeMillis();s.put("done",!s.optBoolean("done"));if(s.optBoolean("done")){if(e.optLong("started_ms")==0)e.put("started_ms",Math.max(d.optLong("started_ms"),now-e.optInt("planned",0)*1000L/Math.max(1,e.getJSONArray("sets").length())));boolean all=true;JSONArray sets=e.getJSONArray("sets");for(int i=0;i<sets.length();i++)all&=sets.getJSONObject(i).optBoolean("done");if(all)e.put("ended_ms",now);advance(ex,now);record(id,s);}else e.put("ended_ms",0);
            boolean hop=s.optBoolean("done");save.run();render();if(hop)hop(ex);}catch(JSONException ignored){}}
    /** In a superset the next open set is in the next exercise, so the page moves there. */
    private void hop(int ex){String g=exercise(ex).optString("group");if(g.isEmpty())return;int n=exercises().length();for(int k=1;k<n;k++){int i=(ex+k)%n;if(g.equals(exercise(i).optString("group"))&&open(exercise(i))>0){View card=list.getChildAt(i*2);if(card!=null)list.post(()->scroll.smoothScrollTo(0,card.getTop()-ui.dp(8)));return;}}}
    /** The next exercise's clock starts when this one finishes. */
    private void advance(int ex,long now)throws JSONException{JSONObject e=exercises().getJSONObject(ex);if(e.optLong("ended_ms")>0&&ex+1<exercises().length()&&exercises().getJSONObject(ex+1).optLong("started_ms")==0)exercises().getJSONObject(ex+1).put("started_ms",now);}
    private int open(JSONObject e){int n=0;JSONArray s=e.optJSONArray("sets");for(int i=0;i<s.length();i++)if(!s.optJSONObject(i).optBoolean("done"))n++;return n;}
    private void record(String id,JSONObject s){try{JSONObject set=new JSONObject().put("kind",s.optString("kind")).put("weight_kg",s.optDouble("weight",0)).put("reps",s.optInt("reps"));double value=WorkoutStore.e1rm(set);if(value<=0)return;JSONArray pr=WorkoutStore.overview(a).optJSONArray("personal_records");double recent=0,all=0;for(int i=0;pr!=null&&i<pr.length();i++){JSONObject r=pr.optJSONObject(i);if(!id.equals(r.optString("exercise_id")))continue;if(r.optJSONObject("recent_best")!=null)recent=r.optJSONObject("recent_best").optDouble("estimated_1rm_kg",0);if(r.optJSONObject("historical_best")!=null)all=r.optJSONObject("historical_best").optDouble("estimated_1rm_kg",0);}if(value>all&&all>0)Toast.makeText(a,"New all-time record · estimated max "+WorkoutUnits.load(a,value),Toast.LENGTH_LONG).show();else if(value>recent&&recent>0)Toast.makeText(a,"New best since your return · estimated max "+WorkoutUnits.load(a,value),Toast.LENGTH_LONG).show();}catch(JSONException ignored){}}
    private void pause(){long now=System.currentTimeMillis();if(d.optLong("paused_ms")>0){put(d,"paused_total",d.optLong("paused_total")+now-d.optLong("paused_ms"));put(d,"paused_ms",0);}else put(d,"paused_ms",now);save.run();update();}
    private void rename(){EditText field=ui.field("Workout name",d.optString("name"));new AlertDialog.Builder(a).setTitle("Workout name").setView(field).setPositiveButton("Save",(x,i)->{String v=field.getText().toString().trim();if(!v.isEmpty()){put(d,"name",v);save.run();((TextView)((LinearLayout)root.getChildAt(0)).getChildAt(1)).setText(v);}}).setNegativeButton("Cancel",null).show();}

    private void replace(int index){JSONObject e=exercise(index);actions=-1;WorkoutPlan.pick(screen,id->{try{String was=WorkoutStore.exerciseName(a,e.optString("eid"));e.put("eid",id);note("edit_exercises","Replaced "+was+" with "+WorkoutStore.exerciseName(a,id));save.run();render();}catch(JSONException ignored){}});}
    private void noteOn(int index){JSONObject e=exercise(index);EditText note=ui.field("Note",e.optString("note"));new AlertDialog.Builder(a).setTitle("Exercise note").setView(note).setPositiveButton("Save",(y,z)->{put(e,"note",note.getText().toString().trim());actions=-1;save.run();render();}).setNegativeButton("Cancel",null).show();}
    private void removeExercise(int index){JSONObject e=exercise(index);exercises().remove(index);actions=-1;note("edit_exercises","Removed "+WorkoutStore.exerciseName(a,e.optString("eid")));tidy();save.run();render();}
    private void move(int from,int to){try{if(to<0||to>=exercises().length()||from==to)return;JSONArray ex=exercises();JSONObject x=ex.getJSONObject(from);if(from<to)for(int i=from;i<to;i++)ex.put(i,ex.getJSONObject(i+1));else for(int i=from;i>to;i--)ex.put(i,ex.getJSONObject(i-1));ex.put(to,x);note("edit_exercises","Reordered exercises");}catch(JSONException ignored){}}
    /** While reordering, cards collapse to their names so the whole order fits on screen; dragging onto a row drops there. */
    private void reorderList(){list.removeAllViews();list.addView(ui.type("Hold and drag to reorder",13,18,500,0,ui.muted),WorkoutViews.gap(ui,8));JSONArray ex=exercises();for(int i=0;i<ex.length();i++){final int at=i;LinearLayout r=ui.row();r.setMinimumHeight(ui.dp(56));r.setPadding(ui.dp(14),0,ui.dp(14),0);r.setBackground(ui.outline(i==reordering?ui.accentSoft:ui.surface,16,ui.stroke,1));r.addView(WorkoutArt.tile(ui,ex.optJSONObject(i).optString("eid"),40),new LinearLayout.LayoutParams(ui.dp(40),ui.dp(40)));r.addView(ui.type(WorkoutStore.exerciseName(a,ex.optJSONObject(i).optString("eid")),15,20,600,0,ui.text),MainParts.weighted(ui,1,10,0,8,0));r.addView(MainParts.icon(ui,"grip",ui.muted),new LinearLayout.LayoutParams(ui.dp(22),ui.dp(22)));r.setOnLongClickListener(v->{v.startDragAndDrop(null,new View.DragShadowBuilder(v),at,0);return true;});r.setOnDragListener((v,e)->{if(e.getAction()==android.view.DragEvent.ACTION_DRAG_ENTERED)v.setAlpha(.55f);else if(e.getAction()==android.view.DragEvent.ACTION_DRAG_EXITED)v.setAlpha(1f);else if(e.getAction()==android.view.DragEvent.ACTION_DROP){move((Integer)e.getLocalState(),at);save.run();reordering=at;main.post(this::reorderList);}return true;});list.addView(r,WorkoutViews.gap(ui,6));}list.addView(ui.primaryButton("Done",()->{reordering=-1;tidy();save.run();render();}));}

    /** The workout in wire format. An active copy keeps open sets so the trainer can adapt them; a finished one holds only ticked sets. */
    JSONObject workout(String status)throws JSONException{JSONArray sets=new JSONArray(),blocks=new JSONArray();JSONObject extras=new JSONObject();JSONArray ex=exercises();boolean finished="completed".equals(status);for(int i=0;i<ex.length();i++){JSONObject e=ex.getJSONObject(i);String id=e.optString("eid");JSONArray rows=e.getJSONArray("sets");for(int k=0;k<rows.length();k++){JSONObject s=rows.getJSONObject(k);if(finished&&!s.optBoolean("done"))continue;JSONObject o=new JSONObject().put("id",s.optString("id")).put("exercise_id",id).put("kind",s.optString("kind","working")).put("completed",s.optBoolean("done"));if(s.has("weight"))o.put("weight_kg",s.optDouble("weight"));if(s.has("reps"))o.put("reps",s.optInt("reps"));if(s.has("rir"))o.put("rir",s.optDouble("rir"));if(s.has("distance"))o.put("distance_m",s.optDouble("distance"));if(s.has("seconds"))o.put("seconds",s.optDouble("seconds"));sets.put(o);}
            JSONObject b=new JSONObject().put("id","b"+i+"-"+d.optString("workout_id")).put("kind",WorkoutStore.cardio(a,id)?"run":"exercise").put("exercise_id",id).put("planned_seconds",Math.min(86400,e.optInt("planned")));if(e.optLong("started_ms")>0){b.put("started_at",iso(e.optLong("started_ms")));if(e.optLong("ended_ms")>=e.optLong("started_ms"))b.put("ended_at",iso(e.optLong("ended_ms")));}blocks.put(b);extras.put(id,new JSONObject().put("note",e.optString("note")).put("rest",e.optInt("rest")).put("group",e.optString("group")));}
        JSONObject o=new JSONObject().put("name",d.optString("name")).put("started_at",iso(d.optLong("started_ms"))).put("timezone",d.optString("timezone")).put("duration_seconds",elapsed()/1000).put("status",status).put("sets",sets).put("blocks",blocks).put("session_changes",d.optJSONArray("changes")).put("notes",d.optString("notes")).put("source",new JSONObject().put("companion",new JSONObject().put("scheduled_date",d.optString("scheduled_date")).put("exercises",extras)));if(!d.isNull("sprint_id"))o.put("sprint_id",d.optString("sprint_id"));if(!d.isNull("template_id"))o.put("template_id",d.optString("template_id"));return o;}

    void finish(){int open=0;JSONArray ex=exercises();for(int i=0;i<ex.length();i++)open+=open(ex.optJSONObject(i));new AlertDialog.Builder(a).setTitle("Finish workout?").setMessage(open>0?open+(open==1?" unticked set":" unticked sets")+" will be left out.":"All sets are ticked.").setPositiveButton("Finish",(x,i)->{main.removeCallbacks(save);try{JSONObject w=workout("completed");JSONObject before=WorkoutStore.overview(a);WorkoutStore.put(a,"workout",d.optString("workout_id"),w);WorkoutStore.clearDraft(a);JSONObject structure=d.isNull("template_id")?null:WorkoutStore.data(a,"template",d.optString("template_id"));JSONArray used=exercises();closed=true;dialog.setOnDismissListener(null);main.removeCallbacks(tick);dialog.dismiss();screen.finished(d.optString("workout_id"),w,before,structure,d.isNull("template_id")?null:d.optString("template_id"),used);}catch(JSONException e){Toast.makeText(a,"Couldn't finish: "+e.getMessage(),Toast.LENGTH_LONG).show();}}).setNegativeButton("Keep going",null).show();}
    private void cancel(){new AlertDialog.Builder(a).setTitle("Cancel workout?").setMessage("Nothing from this session will be kept.").setPositiveButton("Cancel workout",(x,i)->{main.removeCallbacks(save);WorkoutStore.clearDraft(a);if(WorkoutStore.data(a,"workout",d.optString("workout_id"))!=null)WorkoutStore.delete(a,"workout",d.optString("workout_id"));closed=true;dialog.setOnDismissListener(null);dialog.dismiss();screen.liveClosed();}).setNegativeButton("Keep going",null).show();}
    private void trainer(){try{JSONObject w=workout("active");WorkoutStore.put(a,"workout",d.optString("workout_id"),w);}catch(JSONException ignored){}JSONObject context=new JSONObject();try{context.put("workout_id",d.optString("workout_id"));}catch(JSONException ignored){}screen.coach.open(context,this);}
    /** A locally changed set must be sent to the coach again before an older proposal can be applied. */
    boolean matchesSaved(){try{JSONObject saved=WorkoutStore.data(a,"workout",d.optString("workout_id"));if(saved==null)return false;JSONArray old=saved.optJSONArray("sets"),now=workout("active").optJSONArray("sets");if(old==null||now==null||old.length()!=now.length())return false;for(int i=0;i<old.length();i++){JSONObject x=old.getJSONObject(i),y=now.getJSONObject(i);for(String key:new String[]{"id","exercise_id","kind","completed","weight_kg","reps","rir","distance_m","seconds"})if(!x.optString(key,"").equals(y.optString(key,"")))return false;}return true;}catch(JSONException e){return false;}}
    /** After an approved change the session follows the proposal in full, including any corrected ticked sets. */
    void adopt(JSONObject workout){try{JSONArray old=exercises(),sets=workout.optJSONArray("sets"),next=new JSONArray();HashMap<String,JSONObject> kept=new HashMap<>();for(int i=0;i<old.length();i++){JSONObject e=old.getJSONObject(i);kept.put(e.optString("eid"),e);e.put("sets",new JSONArray());}for(int i=0;sets!=null&&i<sets.length();i++){JSONObject s=sets.getJSONObject(i);String id=s.optString("exercise_id");JSONObject e=kept.get(id);if(e==null){e=new JSONObject().put("eid",id).put("rest",120).put("note","").put("group","").put("started_ms",0).put("ended_ms",0).put("planned",240).put("sets",new JSONArray());kept.put(id,e);}if(e.getJSONArray("sets").length()==0)next.put(e);JSONObject row=new JSONObject().put("id",s.optString("id")).put("kind",s.optString("kind","working")).put("done",s.optBoolean("completed"));if(!s.isNull("weight_kg")&&s.has("weight_kg"))row.put("weight",s.optDouble("weight_kg"));if(!s.isNull("reps")&&s.has("reps"))row.put("reps",s.optInt("reps"));if(!s.isNull("rir")&&s.has("rir"))row.put("rir",s.optDouble("rir"));if(!s.isNull("distance_m")&&s.has("distance_m"))row.put("distance",s.optDouble("distance_m"));if(!s.isNull("seconds")&&s.has("seconds"))row.put("seconds",s.optDouble("seconds"));e.getJSONArray("sets").put(row);}d.put("exercises",next);if(!workout.isNull("name")&&workout.has("name"))d.put("name",workout.optString("name"));save.run();render();}catch(JSONException ignored){}}
    /** The owner approved deleting this session: its draft goes too, and the workout closes. */
    void discard(){main.removeCallbacks(save);WorkoutStore.clearDraft(a);closed=true;dialog.setOnDismissListener(null);main.removeCallbacks(tick);dialog.dismiss();screen.liveClosed();}
}
